import React from "react";
import { Link } from "react-router-dom";
import heroImage from "../images/hero.jpg";

// 🔥 Products Images
import img1 from "../assets/1.jpeg";
import img2 from "../assets/2.jpeg";
import img3 from "../assets/3.jpeg";

const Home = () => {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #fff1f8, #e6faff, #fff9e6)",
        padding: "60px 20px",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      {/* HERO SECTION */}
      <div
        style={{
          maxWidth: "1000px",
          margin: "auto",
          padding: "160px 40px",
          borderRadius: "40px",
          textAlign: "center",
          backgroundImage: `url(${heroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          boxShadow: "0 30px 60px rgba(0,0,0,0.12)",
        }}
      >
        <h1
          style={{
            fontSize: "52px",
            color: "#d63384",
            marginBottom: "20px",
            fontWeight: "700",
          }}
        >
          Nanhe Farishte <br /> Kiran Knits
        </h1>

        <p
          style={{
            fontSize: "20px",
            color: "#333",
            marginBottom: "40px",
          }}
        >
          Har bunai mein maa ka pyaar 💖
        </p>

        <Link to="/products">
          <button
            style={{
              background: "linear-gradient(135deg, #ff4f87, #ff85a2)",
              border: "none",
              padding: "16px 45px",
              borderRadius: "50px",
              color: "white",
              fontSize: "18px",
              cursor: "pointer",
            }}
          >
            🛍 Shop Now
          </button>
        </Link>
      </div>

      {/* CATEGORY SECTION */}
      <div
        style={{
          maxWidth: "1100px",
          margin: "100px auto 0",
          textAlign: "center",
        }}
      >
        <h2 style={{ fontSize: "34px", marginBottom: "60px", color: "#444" }}>
          Our Categories
        </h2>

        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: "50px",
            flexWrap: "wrap",
          }}
        >
          <CategoryCard emoji="🧥" title="Sweaters" link="/products?category=Sweater" />
          <CategoryCard emoji="🧦" title="Socks" link="/products?category=Socks" />
          <CategoryCard emoji="🧢" title="Caps" link="/products?category=Cap" />
        </div>
      </div>

      {/* 🔥 PRODUCTS SECTION */}
      <div
        style={{
          maxWidth: "1100px",
          margin: "100px auto 0",
          textAlign: "center",
        }}
      >
        <h2 style={{ fontSize: "34px", marginBottom: "50px", color: "#444" }}>
          Featured Products
        </h2>

        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: "40px",
            flexWrap: "wrap",
          }}
        >
          <ProductCard image={img1} name="Pink Baby Set" price="999" />
          <ProductCard image={img2} name="Blue Baby Set" price="899" />
          <ProductCard image={img3} name="Yellow Baby Set" price="899" />
        </div>
      </div>
    </div>
  );
};

// 🔹 CATEGORY CARD
const CategoryCard = ({ emoji, title, link }) => {
  return (
    <Link to={link} style={{ textDecoration: "none" }}>
      <div
        style={{
          background: "white",
          padding: "70px 40px",
          borderRadius: "30px",
          width: "240px",
          fontSize: "24px",
          fontWeight: "600",
          color: "#444",
          boxShadow: "0 20px 40px rgba(0,0,0,0.1)",
          transition: "0.3s",
        }}
      >
        <div style={{ fontSize: "45px", marginBottom: "15px" }}>
          {emoji}
        </div>
        {title}
      </div>
    </Link>
  );
};

// 🔹 PRODUCT CARD
const ProductCard = ({ image, name, price }) => {
  return (
    <div
      style={{
        background: "white",
        padding: "20px",
        borderRadius: "20px",
        width: "230px",
        boxShadow: "0 15px 35px rgba(0,0,0,0.1)",
        textAlign: "center",
      }}
    >
      <img
        src={image}
        alt={name}
        style={{ width: "100%", borderRadius: "15px" }}
      />

      <h3 style={{ margin: "15px 0 5px", color: "#333" }}>
        {name}
      </h3>

      <p style={{ color: "#d63384", fontWeight: "600" }}>
        ₹{price}
      </p>

      <button
        style={{
          marginTop: "10px",
          padding: "10px 20px",
          border: "none",
          borderRadius: "20px",
          background: "#ff85a2",
          color: "white",
          cursor: "pointer",
        }}
      >
        Add to Cart
      </button>
    </div>
  );
};

export default Home;
